  --bg-2: #111114;
  --bg-3: #16161a;
  --surface: #1c1c21;
  --line: #26262d;
  --text: #ececee;
  --muted: #8b8b94;
  --muted-2: #5c5c64;
  --gold: #c9a96b;
  --gold-2: #e6c98a;
  --accent: #f5f5f7;
  --danger: #ff5e5e;
  --radius: 14px;
  --maxw: 1320px;
  --ease: cubic-bezier(.2,.7,.2,1);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }

.container { max-width: var(--maxw); margin: 0 auto; padding: 0 32px; }

h1, h2, h3, h4 {
  font-family: 'Fraunces', Georgia, serif;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.05;
}
h1 { font-size: clamp(44px, 7vw, 88px); }
h2 { font-size: clamp(28px, 3.6vw, 44px); }
h3 { font-size: 22px; }
em { font-style: italic; color: var(--gold-2); }

.eyebrow {
  display: inline-block;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 14px;
}
.eyebrow.gold { color: var(--gold); }

/* Announcement */
.announcement {
  background: linear-gradient(90deg, #0a0a0b, #15151a, #0a0a0b);
  border-bottom: 1px solid var(--line);
  overflow: hidden;
  font-size: 12px;
  letter-spacing: 0.08em;
  color: var(--muted);
}
.announcement-track {
  display: flex;
  gap: 64px;
  white-space: nowrap;
  padding: 10px 0;
  animation: marquee 35s linear infinite;
}
.announcement-track span { flex-shrink: 0; }
@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(10,10,11,0.75);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 72px;
  gap: 24px;
}
.nav { display: flex; gap: 28px; font-size: 14px; font-weight: 500; }
.nav a {
  position: relative;
  color: var(--text);
  opacity: 0.85;
  transition: opacity .2s var(--ease);
}
.nav a:hover { opacity: 1; }
.nav a::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: -22px;
  height: 1px; background: var(--gold); transform: scaleX(0);
  transition: transform .3s var(--ease);
}
.nav a:hover::after { transform: scaleX(1); }
.nav-sale { color: var(--gold-2) !important; }

.logo {
  font-family: 'Fraunces', serif;
  font-weight: 700;
  font-size: 26px;
  letter-spacing: 0.04em;
  text-align: center;
}
.logo span { color: var(--gold); }

.header-actions { display: flex; gap: 4px; justify-content: flex-end; align-items: center; }
.icon-btn {
  width: 40px; height: 40px;
  display: inline-flex; align-items: center; justify-content: center;
  border-radius: 50%;
  transition: background .2s var(--ease);
  position: relative;
}
.icon-btn:hover { background: var(--surface); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-count {
  position: absolute; top: 4px; right: 4px;
  background: var(--gold); color: #0a0a0b;
  font-size: 10px; font-weight: 700;
  width: 16px; height: 16px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
}
.menu-btn { display: none; }

/* Hero */
.hero {
  position: relative;
  overflow: hidden;
  border-bottom: 1px solid var(--line);
}
.hero-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(circle at 20% 20%, rgba(201,169,107,0.12), transparent 50%),
    radial-gradient(circle at 80% 80%, rgba(120,80,200,0.08), transparent 50%),
    linear-gradient(180deg, #0a0a0b 0%, #101013 100%);
}
.hero-grain {
  position: absolute; inset: 0; opacity: 0.04; pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}
.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 64px;
  align-items: center;
  padding: 88px 32px 96px;
  min-height: 78vh;
}
.hero-text h1 {
  margin: 8px 0 24px;
}
.hero-text > p {
  font-size: 17px;
  color: var(--muted);
  max-width: 520px;
  margin-bottom: 36px;
}
.hero-cta { display: flex; gap: 14px; flex-wrap: wrap; align-items: center; }
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 16px 28px;
  font-size: 14px; font-weight: 500;
  border-radius: 999px;
  letter-spacing: 0.02em;
  transition: all .25s var(--ease);
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent); color: #0a0a0b;
}
.btn-primary:hover { background: var(--gold-2); transform: translateY(-1px); }
.btn-ghost {
  color: var(--text);
  border: 1px solid var(--line);
}
.btn-ghost:hover { border-color: var(--gold); color: var(--gold-2); }
.hero-meta {
  display: flex; gap: 40px; margin-top: 56px;
  padding-top: 28px; border-top: 1px solid var(--line);
  max-width: 520px;
}
.hero-meta div { display: flex; flex-direction: column; }
.hero-meta strong { font-size: 16px; font-weight: 600; }
.hero-meta span { font-size: 12px; color: var(--muted); margin-top: 4px; }

.hero-card {
  position: relative;
  background: var(--surface);
  border-radius: 20px;
  overflow: hidden;
  aspect-ratio: 4/5;
  box-shadow: 0 30px 80px rgba(0,0,0,0.5), inset 0 0 0 1px var(--line);
  transform: rotate(2deg);
  transition: transform .5s var(--ease);
}
.hero-card:hover { transform: rotate(0deg) scale(1.02); }
.hero-card-img {
  position: absolute; inset: 0;
  background-size: cover; background-position: center;
  filter: contrast(1.05) brightness(0.95);
}
.hero-card-info {
  position: absolute; left: 20px; right: 20px; bottom: 20px;
  background: rgba(10,10,11,0.7);
  backdrop-filter: blur(14px);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 12px;
  padding: 16px 18px;
}
.hero-card-info span {
  font-size: 10px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--gold);
}
.hero-card-info h3 { margin: 4px 0 4px; font-size: 20px; }
.hero-card-info p { font-size: 13px; color: var(--muted); }

/* Brand strip */
.brand-strip {
  border-bottom: 1px solid var(--line);
  background: var(--bg-2);
}
.brand-row {
  display: flex; justify-content: space-between; align-items: center;
  padding: 28px 0;
  flex-wrap: wrap; gap: 24px;
}
.brand-row span {
  font-family: 'Fraunces', serif;
  font-weight: 500;
  letter-spacing: 0.18em;
  font-size: 14px;
  color: var(--muted-2);
  transition: color .2s var(--ease);
}
.brand-row span:hover { color: var(--text); }

/* Section heads */
.section-head {
  display: flex; justify-content: space-between; align-items: flex-end;
  margin-bottom: 36px; gap: 24px; flex-wrap: wrap;
}
.section-head h2 { margin-top: 4px; }
.link-arrow {
  font-size: 14px; color: var(--muted);
  border-bottom: 1px solid var(--line);
  padding-bottom: 4px;
  transition: color .2s var(--ease), border-color .2s var(--ease);
}
.link-arrow:hover { color: var(--gold); border-color: var(--gold); }

/* Categories */
.categories { padding: 96px 32px; }
.cat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: 280px 280px;
  gap: 16px;
}
.cat-card {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  background-size: cover; background-position: center;
  transition: transform .5s var(--ease);
  isolation: isolate;
}
.cat-card::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,0.85) 100%);
  z-index: 1;
}
.cat-card:hover { transform: translateY(-4px); }
.cat-card.cat-lg {
  grid-column: span 2; grid-row: span 2;
}
.cat-overlay {
  position: absolute; left: 24px; bottom: 22px; z-index: 2;
}
.cat-overlay h3 { font-size: 26px; margin-bottom: 4px; }
.cat-overlay span { font-size: 12px; color: var(--muted); }
.cat-lg .cat-overlay h3 { font-size: 38px; }

/* Featured Products */
.featured { padding: 32px 32px 96px; }
.filter-tabs { display: flex; gap: 4px; padding: 4px; border: 1px solid var(--line); border-radius: 999px; background: var(--bg-2); }
.filter-tab {
  padding: 10px 18px; border-radius: 999px; font-size: 13px;
  color: var(--muted); transition: all .2s var(--ease);
}
.filter-tab:hover { color: var(--text); }
.filter-tab.active { background: var(--accent); color: #0a0a0b; }

.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  display: flex; flex-direction: column;
  animation: fadeUp .5s var(--ease) both;
}
.product-img {
  position: relative;
  aspect-ratio: 4/5;
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  background-size: cover; background-position: center;
  transition: transform .4s var(--ease);
}
.product:hover .product-img { transform: translateY(-4px); }
.product-img::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.4));
}
.product-tag {
  position: absolute; top: 14px; left: 14px;
  background: rgba(10,10,11,0.7);
  backdrop-filter: blur(8px);
  font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase;
  padding: 6px 10px; border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.08);
  z-index: 2;
}
.product-tag.sale { background: var(--gold); color: #0a0a0b; border-color: transparent; }
.product-tag.new { color: var(--gold-2); }
.product-fav {
  position: absolute; top: 12px; right: 12px; z-index: 2;
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(10,10,11,0.7); backdrop-filter: blur(8px);
  display: flex; align-items: center; justify-content: center;
  border: 1px solid rgba(255,255,255,0.08);
  transition: all .2s var(--ease);
}
.product-fav:hover { background: var(--surface); }
.product-fav.active svg { fill: var(--gold); stroke: var(--gold); }
.product-fav svg { width: 16px; height: 16px; stroke: var(--text); fill: none; stroke-width: 1.5; }

.quick-add {
  position: absolute; left: 14px; right: 14px; bottom: 14px; z-index: 2;
  padding: 12px;
  background: rgba(255,255,255,0.95); color: #0a0a0b;
  border-radius: 999px;
  font-size: 13px; font-weight: 500;
  opacity: 0; transform: translateY(8px);
  transition: all .3s var(--ease);
}
.product:hover .quick-add { opacity: 1; transform: translateY(0); }

.product-info {
  padding: 16px 4px 4px;
  display: flex; justify-content: space-between; align-items: flex-start;
  gap: 12px;
}
.product-name { font-size: 14px; font-weight: 500; margin-bottom: 2px; }
.product-cat { font-size: 12px; color: var(--muted); }
.product-price { display: flex; flex-direction: column; align-items: flex-end; }
.product-price .now { font-size: 14px; font-weight: 600; }
.product-price .was { font-size: 12px; color: var(--muted-2); text-decoration: line-through; }
.product-rating { font-size: 11px; color: var(--gold); margin-top: 6px; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Deals */
.deals {
  background: linear-gradient(180deg, #0c0c0e, #0a0a0b);
  padding: 96px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.section-head.light h2 { color: var(--text); }
.countdown { display: flex; gap: 8px; }
.countdown div {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 12px 16px;
  text-align: center;
  min-width: 64px;
}
.countdown span { display: block; font-family: 'Fraunces', serif; font-size: 24px; font-weight: 600; }
.countdown small { display: block; font-size: 10px; color: var(--muted); letter-spacing: 0.14em; text-transform: uppercase; margin-top: 2px; }

.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: 220px 220px;
  gap: 16px;
}
.deal {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  background-size: cover; background-position: center;
  padding: 24px;
  display: flex; flex-direction: column; justify-content: space-between;
  transition: transform .4s var(--ease);
  border: 1px solid var(--line);
}
.deal:hover { transform: translateY(-4px); }
.deal-hero { grid-row: span 2; padding: 36px; }
.deal-hero h3 { font-size: 38px; max-width: 320px; }
.deal-hero p { color: var(--muted); margin-top: 12px; max-width: 360px; font-size: 14px; }
.deal-tag {
  align-self: flex-start;
  background: var(--gold); color: #0a0a0b;
  padding: 6px 12px; border-radius: 999px;
  font-size: 11px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase;
}
.deal-content h3 { color: #fff; }
.btn-line {
  display: inline-block; margin-top: 12px;
  font-size: 13px; color: var(--gold-2);
  border-bottom: 1px solid currentColor;
  padding-bottom: 2px;
}

/* Editorial */
.editorial { padding: 96px 32px; }
.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 28px;
}
.ed-feature {
  grid-row: span 3;
  display: flex; flex-direction: column;
}
.ed-feature .ed-img { aspect-ratio: 4/5; }
.ed-feature h3 { font-size: 32px; margin: 14px 0; }
.ed-feature h3 a { background-image: linear-gradient(currentColor, currentColor); background-size: 0 1px; background-position: 0 100%; background-repeat: no-repeat; transition: background-size .4s var(--ease); }
.ed-feature h3 a:hover { background-size: 100% 1px; }
.ed-feature p { color: var(--muted); margin-bottom: 18px; }
.ed-author { display: flex; align-items: center; gap: 12px; font-size: 13px; color: var(--muted); }
.avatar { width: 32px; height: 32px; border-radius: 50%; background: linear-gradient(135deg, #c9a96b, #4a3a20); }

.ed-card {
  display: flex; flex-direction: column;
}
.ed-img {
  position: relative;
  display: block;
  aspect-ratio: 4/3;
  border-radius: var(--radius);
  background-size: cover; background-position: center;
  overflow: hidden;
  transition: transform .4s var(--ease);
}
.ed-card .ed-img { aspect-ratio: 4/3.4; }
.ed-card:hover .ed-img { transform: translateY(-3px); }
.ed-badge {
  position: absolute; top: 16px; left: 16px;
  background: rgba(10,10,11,0.7); backdrop-filter: blur(8px);
  border: 1px solid rgba(255,255,255,0.08);
  padding: 6px 12px; border-radius: 999px;
  font-size: 10px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--gold-2);
}
.ed-body { padding-top: 16px; }
.ed-meta { font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--muted); }
.ed-card h4 { font-size: 18px; margin-top: 8px; }
.ed-card h4 a:hover { color: var(--gold-2); }

/* Newsletter */
.newsletter {
  background:
    radial-gradient(circle at 80% 50%, rgba(201,169,107,0.12), transparent 60%),
    var(--bg-2);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  padding: 80px 32px;
  align-items: center;
}
.newsletter h2 { margin: 6px 0 12px; }
.newsletter p { color: var(--muted); max-width: 440px; }
.newsletter-form {
  display: flex; gap: 8px; flex-wrap: wrap;
  position: relative;
}
.newsletter-form input {
  flex: 1; min-width: 240px;
  padding: 18px 22px;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text);
  font-size: 14px; font-family: inherit;
  outline: none;
  transition: border-color .2s var(--ease);
}
.newsletter-form input:focus { border-color: var(--gold); }
.newsletter-form button {
  padding: 18px 32px;
  background: var(--accent); color: #0a0a0b;
  border-radius: 999px;
  font-weight: 500; font-size: 14px;
  transition: all .2s var(--ease);
}
.newsletter-form button:hover { background: var(--gold-2); }
#newsMsg { width: 100%; font-size: 12px; color: var(--gold); margin-top: 4px; min-height: 16px; padding-left: 22px; }

/* Footer */
.footer { padding: 80px 0 32px; background: var(--bg); }
.footer-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr 1fr;
  gap: 40px;
}
.footer-brand p { color: var(--muted); margin: 16px 0 24px; max-width: 280px; font-size: 14px; }
.socials { display: flex; gap: 8px; }
.socials a {
  width: 36px; height: 36px; border-radius: 50%;
  border: 1px solid var(--line);
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 600; letter-spacing: 0.05em;
  color: var(--muted);
  transition: all .2s var(--ease);
}
.socials a:hover { border-color: var(--gold); color: var(--gold); }
.footer-grid h5 {
  font-size: 11px; letter-spacing: 0.18em; text-transform: uppercase;
  color: var(--text); margin-bottom: 18px; font-weight: 600;
}
.footer-grid > div > a {
  display: block; padding: 6px 0;
  font-size: 14px; color: var(--muted);
  transition: color .2s var(--ease);
}
.footer-grid > div > a:hover { color: var(--text); }

.footer-bottom {
  margin-top: 48px;
  padding-top: 24px;
  border-top: 1px solid var(--line);
  display: flex; justify-content: space-between;
  font-size: 12px; color: var(--muted);
  flex-wrap: wrap; gap: 12px;
}

/* Responsive */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; padding: 64px 32px; }
  .hero-card { max-width: 380px; margin: 0 auto; }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .cat-grid { grid-template-columns: repeat(2, 1fr); grid-auto-rows: 220px; }
  .cat-card.cat-lg { grid-column: span 2; grid-row: auto; }
  .deals-grid { grid-template-columns: 1fr 1fr; grid-auto-rows: 200px; }
  .deal-hero { grid-column: span 2; grid-row: auto; min-height: 280px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .ed-feature { grid-column: span 2; grid-row: auto; }
  .ed-feature .ed-img { aspect-ratio: 16/9; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .newsletter-inner { grid-template-columns: 1fr; }
}

@media (max-width: 720px) {
  .container { padding: 0 20px; }
  .nav { display: none; }
  .menu-btn { display: inline-flex; }
  .header-inner { grid-template-columns: auto 1fr auto; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .cat-grid { grid-template-columns: 1fr; grid-auto-rows: 200px; }
  .cat-card.cat-lg { grid-column: auto; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-hero { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .ed-feature { grid-column: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .countdown div { padding: 10px; min-width: 56px; }
  .countdown span { font-size: 20px; }
  .hero-meta { gap: 24px; }
  .section-head { align-items: flex-start; }
}

