+  --gold-2: #e6c98a;
+  --accent: #f5f5f7;
+  --danger: #ff5e5e;
+  --radius: 14px;
+  --maxw: 1320px;
+  --ease: cubic-bezier(.2,.7,.2,1);
+}
+
+* { box-sizing: border-box; margin: 0; padding: 0; }
+
+html, body {
+  background: var(--bg);
+  color: var(--text);
+  font-family: 'Inter', system-ui, -apple-system, sans-serif;
+  font-size: 15px;
+  line-height: 1.55;
+  -webkit-font-smoothing: antialiased;
+  text-rendering: optimizeLegibility;
+}
+
+a { color: inherit; text-decoration: none; }
+img { max-width: 100%; display: block; }
+button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
+
+.container { max-width: var(--maxw); margin: 0 auto; padding: 0 32px; }
+
+h1, h2, h3, h4 {
+  font-family: 'Fraunces', Georgia, serif;
+  font-weight: 600;
+  letter-spacing: -0.02em;
+  line-height: 1.05;
+}
+h1 { font-size: clamp(44px, 7vw, 88px); }
+h2 { font-size: clamp(28px, 3.6vw, 44px); }
+h3 { font-size: 22px; }
+em { font-style: italic; color: var(--gold-2); }
+
+.eyebrow {
+  display: inline-block;
+  font-size: 11px;
+  font-weight: 500;
+  letter-spacing: 0.22em;
+  text-transform: uppercase;
+  color: var(--muted);
+  margin-bottom: 14px;
+}
+.eyebrow.gold { color: var(--gold); }
+
+/* Announcement */
+.announcement {
+  background: linear-gradient(90deg, #0a0a0b, #15151a, #0a0a0b);
+  border-bottom: 1px solid var(--line);
+  overflow: hidden;
+  font-size: 12px;
+  letter-spacing: 0.08em;
+  color: var(--muted);
+}
+.announcement-track {
+  display: flex;
+  gap: 64px;
+  white-space: nowrap;
+  padding: 10px 0;
+  animation: marquee 35s linear infinite;
+}
+.announcement-track span { flex-shrink: 0; }
+@keyframes marquee {
+  from { transform: translateX(0); }
+  to   { transform: translateX(-50%); }
+}
+
+/* Header */
+.header {
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  background: rgba(10,10,11,0.75);
+  backdrop-filter: blur(18px);
+  -webkit-backdrop-filter: blur(18px);
+  border-bottom: 1px solid var(--line);
+}
+.header-inner {
+  display: grid;
+  grid-template-columns: 1fr auto 1fr;
+  align-items: center;
+  height: 72px;
+  gap: 24px;
+}
+.nav { display: flex; gap: 28px; font-size: 14px; font-weight: 500; }
+.nav a {
+  position: relative;
+  color: var(--text);
+  opacity: 0.85;
+  transition: opacity .2s var(--ease);
+}
+.nav a:hover { opacity: 1; }
+.nav a::after {
+  content: ''; position: absolute; left: 0; right: 0; bottom: -22px;
+  height: 1px; background: var(--gold); transform: scaleX(0);
+  transition: transform .3s var(--ease);
+}
+.nav a:hover::after { transform: scaleX(1); }
+.nav-sale { color: var(--gold-2) !important; }
+
+.logo {
+  font-family: 'Fraunces', serif;
+  font-weight: 700;
+  font-size: 26px;
+  letter-spacing: 0.04em;
+  text-align: center;
+}
+.logo span { color: var(--gold); }
+
+.header-actions { display: flex; gap: 4px; justify-content: flex-end; align-items: center; }
+.icon-btn {
+  width: 40px; height: 40px;
+  display: inline-flex; align-items: center; justify-content: center;
+  border-radius: 50%;
+  transition: background .2s var(--ease);
+  position: relative;
+}
+.icon-btn:hover { background: var(--surface); }
+.icon-btn svg { width: 20px; height: 20px; }
+.cart-count {
