+.link-arrow:hover { color: var(--gold); border-color: var(--gold); }
+
+/* Categories */
+.categories { padding: 96px 32px; }
+.cat-grid {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  grid-template-rows: 280px 280px;
