+}
+.product-tag.sale { background: var(--gold); color: #0a0a0b; border-color: transparent; }
+.product-tag.new { color: var(--gold-2); }
+.product-fav {
+  position: absolute; top: 12px; right: 12px; z-index: 2;
+  width: 36px; height: 36px; border-radius: 50%;
+  background: rgba(10,10,11,0.7); backdrop-filter: blur(8px);
+  display: flex; align-items: center; justify-content: center;
+  border: 1px solid rgba(255,255,255,0.08);
+  transition: all .2s var(--ease);
+}
+.product-fav:hover { background: var(--surface); }
+.product-fav.active svg { fill: var(--gold); stroke: var(--gold); }
+.product-fav svg { width: 16px; height: 16px; stroke: var(--text); fill: none; stroke-width: 1.5; }
+
+.quick-add {
+  position: absolute; left: 14px; right: 14px; bottom: 14px; z-index: 2;
