+  opacity: 0; transform: translateY(8px);
+  transition: all .3s var(--ease);
+}
+.product:hover .quick-add { opacity: 1; transform: translateY(0); }
+
+.product-info {
+  padding: 16px 4px 4px;
+  display: flex; justify-content: space-between; align-items: flex-start;
+  gap: 12px;
+}
+.product-name { font-size: 14px; font-weight: 500; margin-bottom: 2px; }
+.product-cat { font-size: 12px; color: var(--muted); }
+.product-price { display: flex; flex-direction: column; align-items: flex-end; }
+.product-price .now { font-size: 14px; font-weight: 600; }
+.product-price .was { font-size: 12px; color: var(--muted-2); text-decoration: line-through; }
+.product-rating { font-size: 11px; color: var(--gold); margin-top: 6px; }
+
+@keyframes fadeUp {
+  from { opacity: 0; transform: translateY(12px); }
