+}
+.ed-body { padding-top: 16px; }
+.ed-meta { font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--muted); }
+.ed-card h4 { font-size: 18px; margin-top: 8px; }
+.ed-card h4 a:hover { color: var(--gold-2); }
+
+/* Newsletter */
+.newsletter {
+  background:
+    radial-gradient(circle at 80% 50%, rgba(201,169,107,0.12), transparent 60%),
+    var(--bg-2);
+  border-top: 1px solid var(--line);
+  border-bottom: 1px solid var(--line);
+}
+.newsletter-inner {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 48px;
+  padding: 80px 32px;
+  align-items: center;
+}
+.newsletter h2 { margin: 6px 0 12px; }
+.newsletter p { color: var(--muted); max-width: 440px; }
+.newsletter-form {
+  display: flex; gap: 8px; flex-wrap: wrap;
+  position: relative;
+}
+.newsletter-form input {
+  flex: 1; min-width: 240px;
+  padding: 18px 22px;
+  background: var(--bg);
+  border: 1px solid var(--line);
+  border-radius: 999px;
+  color: var(--text);
+  font-size: 14px; font-family: inherit;
