+  transition: border-color .2s var(--ease);
+}
+.newsletter-form input:focus { border-color: var(--gold); }
+.newsletter-form button {
+  padding: 18px 32px;
+  background: var(--accent); color: #0a0a0b;
+  border-radius: 999px;
+  font-weight: 500; font-size: 14px;
+  transition: all .2s var(--ease);
+}
+.newsletter-form button:hover { background: var(--gold-2); }
+#newsMsg { width: 100%; font-size: 12px; color: var(--gold); margin-top: 4px; min-height: 16px; padding-left: 22px; }
+
+/* Footer */
+.footer { padding: 80px 0 32px; background: var(--bg); }
+.footer-grid {
+  display: grid;
+  grid-template-columns: 1.6fr 1fr 1fr 1fr;
+  gap: 40px;
+}
+.footer-brand p { color: var(--muted); margin: 16px 0 24px; max-width: 280px; font-size: 14px; }
+.socials { display: flex; gap: 8px; }
+.socials a {
+  width: 36px; height: 36px; border-radius: 50%;
+  border: 1px solid var(--line);
+  display: flex; align-items: center; justify-content: center;
+  font-size: 11px; font-weight: 600; letter-spacing: 0.05em;
