+  flex-wrap: wrap; gap: 12px;
+}
+
+/* Responsive */
+@media (max-width: 1024px) {
+  .hero-inner { grid-template-columns: 1fr; padding: 64px 32px; }
+  .hero-card { max-width: 380px; margin: 0 auto; }
+  .product-grid { grid-template-columns: repeat(2, 1fr); }
+  .cat-grid { grid-template-columns: repeat(2, 1fr); grid-auto-rows: 220px; }
+  .cat-card.cat-lg { grid-column: span 2; grid-row: auto; }
+  .deals-grid { grid-template-columns: 1fr 1fr; grid-auto-rows: 200px; }
+  .deal-hero { grid-column: span 2; grid-row: auto; min-height: 280px; }
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
