+// Render products
+const grid = document.getElementById('productGrid');
+
+function tagHtml(tag) {
+  if (!tag) return '';
+  const label = tag === 'sale' ? 'Sale' : tag === 'new' ? 'New' : tag;
+  return `<span class="product-tag ${tag}">${label}</span>`;
+}
+
+function renderProducts(filter = 'all') {
+  const list = filter === 'all' ? products : products.filter(p => p.filter.includes(filter));
+  grid.innerHTML = list.map((p, i) => `
+    <div class="product" style="animation-delay:${i * 60}ms">
+      <div class="product-img" style="background-image:url('${p.img}')">
+        ${tagHtml(p.tag)}
+        <button class="product-fav" data-id="${p.id}" aria-label="Save">
+          <svg viewBox="0 0 24 24"><path d="M12 21s-7-4.5-9.5-9C1 8 3 4 7 4c2 0 3.5 1 5 3 1.5-2 3-3 5-3 4 0 6 4 4.5 8C19 16.5 12 21 12 21Z"/></svg>
+        </button>
+        <button class="quick-add" data-id="${p.id}">+ Quick Add</button>
+      </div>
+      <div class="product-info">
+        <div>
+          <div class="product-name">${p.name}</div>
+          <div class="product-cat">${p.cat}</div>
+          <div class="product-rating">★ ${p.rating}</div>
+        </div>
+        <div class="product-price">
+          <span class="now">$${p.price}</span>
+          ${p.was ? `<span class="was">$${p.was}</span>` : ''}
+        </div>
+      </div>
+    </div>
+  `).join('');
+}
+
+renderProducts();
+
+// Filter tabs
+document.querySelectorAll('.filter-tab').forEach(tab => {
+  tab.addEventListener('click', () => {
+    document.querySelectorAll('.filter-tab').forEach(t => t.classList.remove('active'));
+    tab.classList.add('active');
+    renderProducts(tab.dataset.filter);
+  });
+});
+
+// Favorites + quick add
+let cartCount = 3;
+const cartCountEl = document.querySelector('.cart-count');
+
+grid.addEventListener('click', (e) => {
+  const fav = e.target.closest('.product-fav');
+  if (fav) { fav.classList.toggle('active'); return; }
+  const qa = e.target.closest('.quick-add');
+  if (qa) {
+    cartCount++;
+    cartCountEl.textContent = cartCount;
+    cartCountEl.animate(
+      [{ transform: 'scale(1)' }, { transform: 'scale(1.4)' }, { transform: 'scale(1)' }],
+      { duration: 300, easing: 'cubic-bezier(.2,.7,.2,1)' }
+    );
+    qa.textContent = '✓ Added';
+    setTimeout(() => { qa.textContent = '+ Quick Add'; }, 1200);
+  }
+});
+
+// Countdown (rolling 3 days)
+const target = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000);
+function updateCountdown() {
+  const diff = Math.max(0, target - Date.now());
+  const d = Math.floor(diff / 86400000);
+  const h = Math.floor((diff % 86400000) / 3600000);
+  const m = Math.floor((diff % 3600000) / 60000);
+  const s = Math.floor((diff % 60000) / 1000);
+  const pad = n => String(n).padStart(2, '0');
+  document.getElementById('d-days').textContent = pad(d);
+  document.getElementById('d-hours').textContent = pad(h);
+  document.getElementById('d-mins').textContent = pad(m);
+  document.getElementById('d-secs').textContent = pad(s);
+}
+updateCountdown();
+setInterval(updateCountdown, 1000);
